mapper.select:
SELECT rc.id as collect_id, rc.room_id, rc.create_time as collect_time, ri.room_number, ri.rent, ai.id as apartment_id, ai.name as apartment_name, ai.introduction as apartment_introduction, ai.district_id as apartment_district_id, ai.district_name as apartment_district_name, ai.city_id as apartment_city_id, ai.city_name as apartment_city_name, ai.province_id as apartment_province_id, ai.province_name as apartment_province_name, ai.address_detail as apartment_address_detail, ai.latitude as apartment_latitude, ai.longitude as apartment_longitude, ai.phone as apartment_phone, ai.is_release as apartment_is_release FROM room_collect rc LEFT JOIN room_info ri ON rc.room_id = ri.id LEFT JOIN apartment_info ai ON ri.apartment_id = ai.id WHERE rc.user_id = #{userId} AND rc.collect_status = 1 AND rc.is_deleted = 0 AND ri.is_deleted = 0 AND ai.is_deleted = 0
AND ai.province_id = #{queryVo.provinceId}
AND ai.city_id = #{queryVo.cityId}
AND ai.district_id = #{queryVo.districtId}
AND ri.rent >= #{queryVo.minRent}
AND ri.rent <= #{queryVo.maxRent}
AND (ri.room_number LIKE CONCAT('%', #{queryVo.roomName}, '%') OR ai.name LIKE CONCAT('%', #{queryVo.roomName}, '%'))
ORDER BY rc.create_time ASC
ORDER BY rc.create_time DESC

SELECT COUNT(1) > 0
FROM room_collect 
WHERE user_id = #{userId} 
  AND room_id = #{roomId} 
  AND collect_status = 1
  AND is_deleted = 0

mapper.update:
UPDATE room_collect 
SET collect_status = #{collectStatus},
    update_time = NOW()
WHERE user_id = #{userId} 
  AND room_id = #{roomId} 
  AND is_deleted = 0

UPDATE room_collect SET collect_status = #{status}, update_time = NOW() WHERE user_id = #{userId} AND id IN
#{id}
AND is_deleted = 0
